	private readonly \Closure $provider;private readonly ?\Closure $authorize;private readonly string $name;private readonly ?string $tenantField;private readonly bool $requireTenant;private readonly int $maxRows;private readonly bool $snapshotConsistent;
	/** @param array<string,mixed> $options */
	public function __construct(callable $provider,array $options=[]){
		$unknown=array_values(array_diff(array_keys($options),['name','authorize','tenant_field','require_tenant','max_rows','snapshot_consistent']));if($unknown!==[]){throw new \InvalidArgumentException('Unknown array semantic backend option: '.(string)$unknown[0]);}
		$this->provider=\Closure::fromCallable($provider);if(array_key_exists('authorize',$options)&&!is_callable($options['authorize'])){throw new \InvalidArgumentException('Array semantic authorization must be callable.');}$this->authorize=isset($options['authorize'])?\Closure::fromCallable($options['authorize']):null;
		$this->name=PanelOperationsGuard::name((string)($options['name']??'semantic_array'),'semantic backend');$tenant=array_key_exists('tenant_field',$options)?$options['tenant_field']:'tenant_id';if($tenant!==null&&!is_string($tenant)){throw new \InvalidArgumentException('Array semantic tenant_field must be a string or null.');}$this->tenantField=$tenant===null?null:PanelQueryPath::make($tenant)->value();$require=$options['require_tenant']??($this->tenantField!==null);if(!is_bool($require)||($require&&$this->tenantField===null)){throw new \InvalidArgumentException('Array semantic require_tenant needs a tenant field.');}$this->requireTenant=$require;
