	public function name():string{return$this->name;}/** @return array<string,mixed> */public function capabilities():array{return['type'=>'panel_semantic_backend_capabilities','version'=>1,'backend'=>$this->name,'entities'=>'provider_defined','aggregations'=>PanelSemanticMetric::AGGREGATIONS,'typed_filters'=>true,'relations'=>true,'group_by'=>true,'multi_metric'=>true,'pushdown'=>false,'snapshot_consistent'=>$this->snapshotConsistent,'tenant'=>$this->tenantField!==null,'authorization'=>$this->authorize!==null,'max_rows'=>$this->maxRows,'max_groups'=>10000];}
	/** @return list<string> */public function unsupported(PanelSemanticExecutionPlan $plan):array{$missing=[];$query=$plan->query();if($this->authorize===null){$missing[]='authorization';}if($query->tenantKey()!==null&&$this->tenantField===null){$missing[]='tenant';}if($query->consistency()==='snapshot'&&!$this->snapshotConsistent){$missing[]='snapshot_consistency';}return$missing;}
