		try{$provided=($this->provider)($plan->entity(),$query,$plan);}catch(\Throwable $error){throw new PanelSemanticException('semantic_source_unavailable','The semantic row provider is unavailable.',503,true,$error);}if(!is_iterable($provided)){throw new PanelSemanticException('semantic_source_invalid','The semantic row provider returned an invalid result.',503,false);}
