		return new PanelSemanticQueryResult($plan,$page,$total,$this->name,false,$this->snapshotConsistent,['rows_scanned'=>count($rows),'groups'=>$total,'aggregation_pushdown'=>false,'filter_pushdown'=>false,'fallback'=>false]);
	}
	/** @param list<array{dimensions:array<string,mixed>,metrics:array<string,mixed>}> $rows */private function sort(array &$rows,PanelSemanticQuery $query):void{$sorts=$query->sorts();if($sorts===[]){$sorts=array_map(static fn(string $dimension):PanelSemanticSort=>PanelSemanticSort::asc($dimension),$query->dimensions());}usort($rows,function(array $left,array $right)use($sorts):int{foreach($sorts as$sort){$a=array_key_exists($sort->target(),$left['dimensions'])?$left['dimensions'][$sort->target()]:$left['metrics'][$sort->target()];$b=array_key_exists($sort->target(),$right['dimensions'])?$right['dimensions'][$sort->target()]:$right['metrics'][$sort->target()];$explicitNull=$a===null||$b===null;$comparison=$this->compare($a,$b,$sort->nulls());if($comparison!==0){return!$explicitNull&&$sort->direction()==='desc'?-$comparison:$comparison;}}return PanelOperationsGuard::json($left['dimensions'])<=>PanelOperationsGuard::json($right['dimensions']);});}
	private function compare(mixed $a,mixed $b,string $nulls):int{if($a===null||$b===null){if($a===$b){return 0;}return$a===null?($nulls==='first'?-1:1):($nulls==='first'?1:-1);}if(is_numeric($a)&&is_numeric($b)){return(float)$a<=>(float)$b;}return strnatcasecmp((string)$a,(string)$b);}
