	/** @return array<string,mixed> */public function jsonSerialize():array{return['type'=>'panel_array_semantic_backend_manifest','version'=>1,'name'=>$this->name,'capabilities'=>$this->capabilities(),'provider_serialized'=>false,'authorization_callback_serialized'=>false,'default_deny'=>$this->authorize===null];}
}
